import {
  OjinClient,
  OjinEvent,
  FrameType,
  OjinInteractionResponseMessage,
  OjinTextInputMessage,
  OjinEndInteractionMessage,
} from "ojin-client";

// Replace with your own downstream transport instance.
// The shape below is illustrative — adapt send() to match your protocol.
declare const myTransport: {
  send(payload: {
    interactionId: string;
    video: Uint8Array;
    audio: Uint8Array;
    isFinal: boolean;
    isIdle: boolean;
  }): void;
};

const client = new OjinClient({
  wsUrl: process.env.OJIN_WS_URL!,
  apiKey: process.env.OJIN_API_KEY!,
  configId: process.env.OJIN_CONFIG_ID!,
});

// Register the frame handler before connect() so no frames are missed.
client.events.on(OjinEvent.InteractionResponse, (msg: OjinInteractionResponseMessage) => {
  myTransport.send({
    interactionId: msg.interactionId,
    video: msg.videoFrameBytes,   // JPEG-encoded frame — render directly
    audio: msg.audioFrameBytes,   // PCM int16, 16 kHz, mono — play via AudioContext
    isFinal: msg.isFinalResponse, // true on the last frame of an interaction
    isIdle: msg.frameType === FrameType.Idle, // idle frames for looping background
  });
});

await client.connect();
await client.waitForReady();

await client.sendMessage(new OjinTextInputMessage("Hello!"));
await client.sendMessage(new OjinEndInteractionMessage());
